<script setup>
import {computed,onBeforeUnmount,onMounted,ref} from 'vue';
import {readCounts,mergeCounts,analyticsKey} from '../../services/analytics.js';
import {downloadJson,saveLocal} from '../../room/storage.js';
import {withCloudDeadline,cloudServiceMessage} from '../../services/cloudConnection.js';
import {fetchUsageCounts} from '../../services/usageCounts.js';
import {activityCatalog} from '../../data/activityCatalog.js';
import {siteSections} from '../../data/siteSections.js';
const data=ref(readCounts()),scope=ref('local'),span=ref(7),message=ref(''),busy=ref(false),file=ref(null),remote=ref(null),canClear=ref(false);
const configured=import.meta.env.VITE_SITE_ANALYTICS==='enabled';let alive=true;const controller=new AbortController();
function refresh(){data.value=readCounts();}
const names={home:'小屋首页',gallery:'心动收藏',works:'我的作品架',...Object.fromEntries([...activityCatalog,...siteSections].map(c=>[c.id,c.title]))};
const rows=computed(()=>{const result={};const since=new Date(Date.now()-(span.value-1)*86400000).toISOString().slice(0,10);for(const [day,targets] of Object.entries((scope.value==='global'?remote.value:data.value)?.days||{})){if(day<since)continue;for(const [id,c] of Object.entries(targets)){result[id]??={id,open:0,complete:0,export:0};for(const k of ['open','complete','export'])result[id][k]+=c[k]||0;}}return Object.values(result).sort((a,b)=>b.open-a.open||b.complete-a.complete);});
const total=computed(()=>rows.value.reduce((a,r)=>({open:a.open+r.open,complete:a.complete+r.complete,export:a.export+r.export}),{open:0,complete:0,export:0}));
async function loadGlobal(){scope.value='global';if(!configured){message.value='全站汇总尚未启用。本机计数可直接使用；站主启用统计接口后可在这里查看汇总。';return;}busy.value=true;try{const counts=await withCloudDeadline(async signal=>{const {getCloudClient,isGalleryAdmin}=await import('../../services/galleryCloud.js');if(!await isGalleryAdmin(signal))throw new Error('请先用已有站主账号登录图片管理，再回来看板刷新。');return fetchUsageCounts(await getCloudClient(),{signal});},{signal:controller.signal});if(alive){remote.value=counts;message.value='已读取全站匿名汇总。';}}catch(e){if(alive)message.value=e.code==='CLOUD_TIMEOUT'?cloudServiceMessage(e):e.message;}finally{if(alive)busy.value=false;}}
async function importFile(e){const f=e.target.files?.[0];if(!f)return;try{if(f.size>200000)throw new Error('备份不能超过200KB。');const text=await f.text();if(!alive)return;data.value=mergeCounts(text);message.value='已恢复统计备份；重复日期按较大值合并，避免重复导入累加。';}catch(e){message.value=e.message;}finally{e.target.value='';}}
function clear(){if(saveLocal(analyticsKey,{version:1,days:{}})){refresh();canClear.value=false;message.value='本机计数已清空，作品与其他数据保留。';}else message.value='未能清空计数。';}
onMounted(()=>{window.addEventListener('hitori:counts',refresh);window.addEventListener('storage',refresh);});onBeforeUnmount(()=>{alive=false;controller.abort();window.removeEventListener('hitori:counts',refresh);window.removeEventListener('storage',refresh);});
</script>
<template><section class="room-panel" aria-labelledby="stats-title"><p class="play-eyebrow">用真实的体验次数，找到下一步方向</p><h2 id="stats-title">小屋运营看板</h2><div class="room-actions"><button type="button" :aria-pressed="scope==='local'" @click="scope='local';message=''">本机统计</button><button type="button" :aria-pressed="scope==='global'" :disabled="busy" @click="loadGlobal">{{busy?'读取中…':'全站汇总'}}</button></div><p class="room-intro">{{scope==='local'?'当前数据仅来自这台浏览器，不能代表全站访客。':'全站汇总由站主启用接口后提供，仅站主账号可读取。'}} 只记录日期、活动编号和计数；不记录身份、搜索词或作品内容。完成数包括完成活动与收好作品的动作，不是独立人数。</p><label class="room-field">统计范围<select v-model.number="span"><option :value="7">最近7天</option><option :value="30">最近30天</option><option :value="90">最近90天</option></select></label><div class="room-stats"><div><small>打开次数</small><div class="metrics-number">{{total.open}}</div></div><div><small>完成动作</small><div class="metrics-number">{{total.complete}}</div></div><div><small>成功导出</small><div class="metrics-number">{{total.export}}</div></div></div><table v-if="rows.length"><thead><tr><th>内容</th><th>打开</th><th>完成</th><th>导出</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><th>{{names[r.id]||r.id}}</th><td>{{r.open}}</td><td>{{r.complete}}</td><td>{{r.export}}</td></tr></tbody></table><p v-else>这个范围内暂时没有记录。去活动室体验后回来看看。</p><p class="room-status" role="status">{{message}}</p><div v-if="scope==='local'" class="room-actions"><button type="button" @click="downloadJson(data,'hitori-usage-counts.json')">导出统计备份</button><button type="button" @click="file.click()">导入统计备份</button><input ref="file" hidden type="file" accept=".json,application/json" aria-label="选择统计备份" @change="importFile"><button type="button" @click="canClear=!canClear">清空本机计数</button><button v-if="canClear" type="button" @click="clear">确认清空计数</button></div><p class="room-hint">可在顶部工具面板关闭“记录匿名体验次数”。全站汇总需完成一次性统计接口配置；未启用时不会发送计数。</p><RouterLink to="/manage-gallery">站主登录入口 ↗</RouterLink></section></template>
